function postCard($r){global $me;$author=h($r['display_name']);if($r['visible']||$r['user_id']==$me['id'])$author='<a href="'.h(linkTo('profile',$r['user_id'])).'">'.$author.'</a>';$s='<div class="row"><span class="avatar">✦</span><strong>'.$author.'</strong>'.(!empty($r['is_bot'])?'<span class="pill">BOT · Demo</span>':'').'<span class="meta">'.h($r['created_at']).'</span></div>';if(($r['review_status']??'approved')!=='approved')$s.='<span class="pill">'.h($r['review_status']==='pending'?'Pendiente de moderación':'No aprobado').'</span>';if($r['kind']==='forum')$s.='<span class="pill">'.h($r['category']).'</span><h2><a href="'.h(linkTo('thread',$r['id'])).'">'.h($r['title']).'</a></h2>';$s.='<div class="body">'.h($r['body']).'</div>';if($r['kind']==='forum')$s.='<p><a href="'.h(linkTo('thread',$r['id'])).'">Leer y responder →</a></p>';if(($r['review_status']??'approved')==='approved'){$n=(int)one('SELECT COUNT(*) AS n FROM studio_reactions WHERE post_id=?',[$r['id']])['n'];$liked=one('SELECT 1 FROM studio_reactions WHERE post_id=? AND user_id=?',[$r['id'],$me['id']]);$s.=form('react',hidden('target',$r['id']),($liked?'♥':'♡').' Me identifico · '.$n);if($r['user_id']!=$me['id'])$s.='<details><summary>Denunciar</summary>'.form('report_post',hidden('target',$r['id']).input('reason','Motivo','','text','required maxlength="300"'),'Enviar denuncia').'</details>';}if($me['role']==='admin'||$r['user_id']==$me['id'])$s.=form('delete_post',hidden('id',$r['id']),'Eliminar mensaje');return card($s);}
$join='SELECT p.*,u.display_name,u.visible,COALESCE((SELECT status FROM studio_post_reviews WHERE post_id=p.id),\'approved\') AS review_status,EXISTS(SELECT 1 FROM studio_demo_bots b WHERE b.user_id=u.id) AS is_bot FROM studio_posts p JOIN studio_users u ON u.id=p.user_id ';
if($v==='wall'||$v==='forum'){$forum=$v==='forum';$body.='<div class="studio-section-hero"><div><div class="eyebrow">Pluma Libre · Comunidad</div><h1>'.($forum?'Foro':'Muro').'</h1><p>'.($forum?'Conversaciones por temas.':'Compartí ideas, experiencias y pequeños logros.').'</p></div>'.studioArt('pluma').'</div>';$f='';if($forum){$f='<label>Categoría</label><select name="category">';foreach($cats as $c)$f.='<option>'.h($c).'</option>';$f.='</select>'.input('title','Título','','text','required maxlength="120"');}$body.=card('<h2>'.($forum?'Abrir un tema':'Dejá un mensaje').'</h2>'.form($forum?'topic':'post',$f.area('body','Mensaje'),'Publicar'));$r=rows($join.'WHERE p.kind=? AND u.active=1'.studioPostFilter().' ORDER BY p.id DESC LIMIT 50',[$forum?'forum':'wall']);if(!$r)$body.='<p>Aún no hay mensajes.</p>';foreach($r as $x)$body.=postCard($x);page($v,$body);}
if($v==='thread'){$r=one($join."WHERE p.id=? AND p.kind='forum' AND u.active=1".studioPostFilter(),[$id]);if(!$r)page('Tema',card('Tema no disponible.'));$body.=postCard($r);if($r['review_status']!=='approved')page('Tema',$body);foreach(rows($join.'WHERE p.parent_id=? AND u.active=1'.studioPostFilter().' ORDER BY p.id LIMIT 100',[$id])as $x)$body.=postCard($x);$body.=card('<h2>Responder</h2>'.form('reply',hidden('parent',$id).area('body','Mensaje'),'Responder'));page('Tema',$body);}
if($v==='members'){
 $body.='<div class="studio-section-hero"><div><div class="eyebrow">Studio · El club</div><h1>Perfiles</h1><p>Explorá las fichas de quienes eligieron compartir su perfil con la comunidad. Tu ficha privada solo la ves vos.</p><p><a class="btn alt" href="'.h(linkTo('profile',$me['id'])).'">Mi ficha</a></p></div>'.studioArt('perfiles').'</div>';
 $members=rows('SELECT u.id,u.display_name,u.style,u.bio,u.visible,u.avatar IS NOT NULL AS has_avatar,EXISTS(SELECT 1 FROM studio_demo_bots b WHERE b.user_id=u.id) AS is_bot FROM studio_users u WHERE u.active=1 AND (u.visible=1 OR u.id=?) ORDER BY CASE WHEN u.id=? THEN 0 ELSE 1 END,u.id DESC LIMIT 100',[$me['id'],$me['id']]);
 $body.='<div class="studio-profile-grid">';
 foreach($members as $u){if(studioBlocked((int)$me['id'],(int)$u['id']))continue;
  $own=(int)$u['id']===(int)$me['id'];
  $body.='<article class="studio-member-card"><div class="studio-member-cover">'.studioArt('perfiles').'</div><div class="studio-member-body">'.avatar($u,true).'<h2>'.h($u['display_name']).'</h2>'.(!empty($u['is_bot'])?'<span class="pill">BOT · Demo</span>':'').($own?'<span class="pill">'.($u['visible']?'Mi ficha':'Mi ficha privada').'</span>':'').'<p>'.h($u['style']?:'Explorando mi estilo').'</p><a class="btn alt" href="'.h(linkTo('profile',$u['id'])).'">Ver ficha</a></div></article>';
 }
 if(!$members)$body.='<p>Todavía no hay fichas visibles.</p>';
 page('Perfiles',$body.'</div>');
}
if($v==='profile'){$u=one('SELECT id,display_name,style,bio,visible,avatar IS NOT NULL AS has_avatar,EXISTS(SELECT 1 FROM studio_demo_bots b WHERE b.user_id=studio_users.id) AS is_bot FROM studio_users WHERE id=? AND active=1',[$id?:$me['id']]);$own=$u&&$u['id']==$me['id'];if(!$u||(!$own&&(!$u['visible']||studioBlocked((int)$me['id'],(int)$u['id'])))){http_response_code(404);page('Perfil',card('Ficha privada o no disponible.'));}
$body.='<div class="hero row">'.avatar($u,true).'<div><div class="eyebrow">Ficha personal</div><h1>'.h($u['display_name']).'</h1>'.(!empty($u['is_bot'])?'<span class="pill">BOT · Demo</span> ':'').'<span class="pill">'.h($u['style']?:'Explorando mi estilo').'</span>'.($own?' <span class="pill">'.($u['visible']?'Visible a miembros':'Privada').'</span>':'').'</div></div>'.card('<h2>Sobre mí</h2><div class="body">'.h($u['bio']?:'Todavía no hay descripción.').'</div>');
if($own){$body.=card('<h2>Editar mi ficha</h2>'.form('profile',input('display_name','Nombre visible',$u['display_name'],'text','required maxlength="60"').input('style','Mi estilo',$u['style'],'text','maxlength="100"').area('bio','Sobre mí',$u['bio'],600).input('avatar','Avatar JPG, PNG o WebP hasta 2 MB','','file','accept="image/jpeg,image/png,image/webp"').check('remove_avatar','Quitar avatar').check('visible','Compartir mi ficha y avatar con miembros registrados',(bool)$u['visible']),'Guardar',true)).card('<h2>Cambiar contraseña</h2>'.form('password',input('current','Contraseña actual','','password','required autocomplete="current-password"').input('password','Nueva contraseña','','password','required minlength="12" maxlength="72" autocomplete="new-password"'),'Actualizar'));}if(!$own)$body.=card(form('block',hidden('target',$u['id']),'Bloquear usuario'));if($own){$body.=studioMeasureCard();$blocked=rows('SELECT u.id,u.display_name FROM studio_blocks b JOIN studio_users u ON u.id=b.blocked_id WHERE b.blocker_id=?',[$me['id']]);$list='<h2>Usuarios bloqueados</h2>';foreach($blocked as $bl)$list.='<p>'.h($bl['display_name']).'</p>'.form('unblock',hidden('target',$bl['id']),'Desbloquear');if(!$blocked)$list.='<p>No bloqueaste a nadie.</p>';$body.=card($list);}if($own)$body.=card('<h2>Cuenta</h2>'.form('logout','','Cerrar sesión'));page('Perfil',$body);}
if($v==='admin'){$body.=hero('Administración de usuarios','Altas, edición, suspensión, bajas y moderación. Registro: '.($open?'abierto':'cerrado').'.').card('<h2>Alta manual</h2>'.form('admin_create',accountFields(),'Crear usuario')).card('<h2>Laboratorio de bots</h2><p>Genera un mensaje identificado como demo y agrega 5 XP a un bot activo. No representa actividad real.</p>'.form('demo_activity','','Simular actividad'));$t='<h2>Listado</h2><div class="table"><table><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';foreach(rows('SELECT id,username,display_name,role,active FROM studio_users ORDER BY id DESC LIMIT 200')as $u)$t.='<tr><td>'.h($u['username']).'</td><td>'.h($u['display_name']).'</td><td>'.h($u['role']).'</td><td>'.($u['active']?'Activo':'Suspendido').'</td><td>'.($u['role']==='member'?'<a href="'.h(linkTo('edituser',$u['id'])).'">Editar / baja</a>':'').'</td></tr>';page('Administración',$body.card($t.'</tbody></table></div>').studioModerationCards());}
if($v==='edituser'){$u=one("SELECT id,username,display_name,active FROM studio_users WHERE id=? AND role='member'",[$id]);if(!$u)page('Editar',card('Usuario no disponible.'));$body.=card('<h2>Editar usuario</h2>'.form('admin_update',hidden('id',$id).input('username','Usuario',$u['username'],'text','required maxlength="32"').input('display_name','Nombre visible',$u['display_name'],'text','required maxlength="60"').input('password','Nueva contraseña (opcional)','','password','minlength="12" maxlength="72" autocomplete="new-password"').check('active','Cuenta activa',(bool)$u['active']),'Guardar')).card('<h2>Baja definitiva</h2><p>Elimina la cuenta, avatar y mensajes, incluidas las respuestas de sus temas.</p>'.form('admin_delete',hidden('id',$id).check('confirm','Confirmo la eliminación irreversible.'),'Eliminar cuenta'));page('Editar',$body);}
